from decimal import Decimal, InvalidOperation
from io import StringIO
import pandas as pd

def csv_catalog(csv_text, min_stock):
    def whole(text):
        try:
            number = Decimal(text)
        except (InvalidOperation, TypeError):
            return None
        if not number.is_finite() or number != number.to_integral_value():
            return None
        return int(number)

    df = pd.read_csv(StringIO(csv_text), dtype='string', keep_default_na=False)
    df['sku'] = df['sku'].str.strip()
    for name in ['stock', 'price']:
        df[name] = pd.Series([whole(text) for text in df[name]], index=df.index, dtype=object)
    df = df.dropna(subset=['stock', 'price'])
    mask = df['sku'].ne('') & df['stock'].ge(min_stock) & df['price'].ge(0)
    valid = df.loc[mask].copy()
    valid['value'] = valid['stock'] * valid['price']
    valid = valid.sort_values(['value', 'sku'], ascending=[False, True])
    return [{'sku': row.sku, 'stock': int(row.stock), 'value': int(row.value)}
            for row in valid[['sku', 'stock', 'value']].itertuples(index=False)]

