import pandas as pd

def checked_revenue(orders, catalog):
    sales = pd.DataFrame(orders, columns=['sku', 'qty'], dtype=object)
    products = pd.DataFrame(catalog, columns=['sku', 'price'], dtype=object)
    for frame in [sales, products]:
        if frame['sku'].isna().any() or frame['sku'].astype('string').str.strip().eq('').any():
            raise ValueError('sku должен быть непустым')
    if products['sku'].duplicated().any():
        raise ValueError('sku каталога должен быть уникальным')
    if sales['qty'].isna().any() or sales['qty'].le(0).any():
        raise ValueError('qty должен быть известным и положительным')
    if products['price'].isna().any() or products['price'].lt(0).any():
        raise ValueError('price должен быть известным и неотрицательным')
    joined = sales.merge(products, on='sku', how='left',
                         validate='many_to_one', indicator=True)
    if not joined['_merge'].eq('both').all():
        raise ValueError('В заказе есть неизвестный sku')
    joined['revenue'] = joined['qty'] * joined['price']
    totals = joined.groupby('sku', sort=True)['revenue'].sum()
    return {sku: int(value) for sku, value in totals.items()}

